<?php require_once 'config/functions.php';require_login();$uid=user_id();if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();if(isset($_POST['add_habit'])){$name=trim($_POST['name']??'');if($name)$pdo->prepare('INSERT INTO habits(user_id,name) VALUES(?,?)')->execute([$uid,$name]);flash('Habit added.');}elseif(isset($_POST['habit_id'])){$id=(int)$_POST['habit_id'];$date=$_POST['log_date']??date('Y-m-d');$done=isset($_POST['completed']);if($done)$pdo->prepare('INSERT INTO habit_logs(habit_id,log_date,completed) VALUES(?,?,1) ON DUPLICATE KEY UPDATE completed=1')->execute([$id,$date]);else $pdo->prepare('DELETE FROM habit_logs WHERE habit_id=? AND log_date=?')->execute([$id,$date]);}elseif(isset($_POST['delete_habit'])){$pdo->prepare('DELETE FROM habits WHERE id=? AND user_id=?')->execute([(int)$_POST['delete_habit'],$uid]);flash('Habit removed.');}redirect('habits.php');}$date=$_GET['date']??date('Y-m-d');$q=$pdo->prepare('SELECT h.id,h.name,IFNULL(l.completed,0) completed FROM habits h LEFT JOIN habit_logs l ON l.habit_id=h.id AND l.log_date=? WHERE h.user_id=? ORDER BY h.id DESC');$q->execute([$date,$uid]);$habits=$q->fetchAll();page_header('Habit Tracker');?><div class="grid grid-2"><div class="card"><h3>Add a healthy habit</h3><form method="post" class="row"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input name="name" placeholder="e.g. Drink 8 glasses of water" required><button name="add_habit">Add Habit</button></form><p class="small">Start small. Consistency is more important than perfection.</p></div><div class="card"><h3>Daily check-in</h3><form class="row" method="get"><label>Date</label><input type="date" name="date" value="<?=h($date)?>"><button>View</button></form><p class="stat"><?=count(array_filter($habits,fn($a)=>$a['completed']))?> / <?=count($habits)?></p><div class="progress"><div style="width:<?=count($habits)?100*count(array_filter($habits,fn($a)=>$a['completed']))/count($habits):0?>%"></div></div></div></div><div class="card" style="margin-top:18px"><h3>Your habits · <?=h($date)?></h3><?php if(!$habits):?><div class="empty">Add your first habit above.</div><?php else:foreach($habits as $hbt):?><div class="row" style="justify-content:space-between;border-bottom:1px solid var(--line);padding:12px 0"><form method="post" class="row"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="habit_id" value="<?=$hbt['id']?>"><input type="hidden" name="log_date" value="<?=h($date)?>"><label><input type="checkbox" name="completed" value="1" <?=$hbt['completed']?'checked':''?> onchange="this.form.submit()"> <?=h($hbt['name'])?></label></form><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><button class="btn danger" name="delete_habit" value="<?=$hbt['id']?>" data-confirm="Remove this habit and its logs?">Remove</button></form></div><?php endforeach;endif;?></div><?php page_footer();
